terminal=[]
for pid,start,unit,invocation in [(331715, '74886713', 'enclave-rpc-chain-guest-seed-r1-20261101.service', '1464d91f81f4417cab80c90582f369c3'), (331657, '74885604', 'enclave-rpc-chain-guest-admission-r1-20261101.service', '5d447cf8c7ba4cab9aa3dbd79269f522')]:
 path=Path('/proc')/str(pid)/'stat';actual=path.read_text().rsplit(')',1)[1].split()[19]if path.exists()else None
 assert actual!=start,'Exact prior process still live'
 r=subprocess.run(['/usr/bin/systemctl','show',unit,'-p','MainPID','-p','ActiveState','-p','ExecMainStatus','-p','InvocationID'],capture_output=True,text=True,timeout=3,check=True)
 assert 'MainPID=0\n' in r.stdout and 'ExecMainStatus=0\n' in r.stdout and 'ActiveState=inactive\n' in r.stdout
 terminal.append({'pid':pid,'expectedStart':start,'actualStart':actual,'unit':unit,'completedInvocation':invocation,'state':r.stdout})
mem=next(int(x.split()[1])*1024 for x in Path('/proc/meminfo').read_text().splitlines() if x.startswith('MemAvailable:'));assert mem>=2*1024**3+128*1024**2
p=root/'output';iso=p/'seed.iso'
