with iso.open('rb') as f:assert hashlib.file_digest(f,'sha256').hexdigest()==expected['sha256']
for name,sha in {'prepare_seed.py': 'a6ffc88230f6b8db4aa98eadf4f8352b0ac9a35ad077a299c831276255a5ce51', 'credentials.py': 'b02baf0cbf2b71fed1caded598381c59763dd885c1867b6ea2e69bc009508158'}.items():
 assert hashlib.sha256((root/name).read_bytes()).hexdigest()==sha
spec=importlib.util.spec_from_file_location('credentials',root/'credentials.py');credentials=importlib.util.module_from_spec(spec);spec.loader.exec_module(credentials)
writes,fragment,public=credentials.seed_material(config,expected['instance'])
user=(p/'readback/user-data').read_text();assert user.startswith('#cloud-config\n')
assert user==(p/'seed/user-data').read_text();cloud=json.loads(user.split('\n',1)[1]);records=expected['records']
assert len(cloud['write_files'])==len(records)==40
assert {x['path'] for x in cloud['write_files']}==set(records)
syntax=0
for row in cloud['write_files']:
 data=base64.b64decode(row['content'],validate=True);record=records[row['path']]
 assert row['owner']=='root:root' and row['permissions']==record['mode'] and len(data)==record['bytes']
 if record.get('private'):
  assert row['path'] in writes and data==writes[row['path']]['data'] and 'sha256' not in record
 else:assert hashlib.sha256(data).hexdigest()==record['sha256']
 if row['path'].endswith('.py'):compile(data,row['path'],'exec');syntax+=1
for key,value in fragment.items():assert cloud[key]==value
assert '/etc/enclave-rpc/activation-request.json' not in records and '/etc/enclave-rpc/server-ready.json' not in records
assert '/opt/enclave-rpc/activate_storage.py' in records and '/etc/systemd/system/enclave-rpc-storage-activation.service' in records
assert '/etc/enclave-rpc/jwt.hex' not in records and '/etc/enclave-rpc/attachment.json' not in records
assert not any('/issuer/' in path or path.endswith('server-key.pem') for path in records)
assert cloud['runcmd']==[['/usr/bin/systemctl','daemon-reload'],['/usr/bin/systemctl','start','enclave-rpc-identity.service']]
